# -*- coding: utf-8 -*-
"""Generate the versioned interchange contract and the bundled offline example."""
import json
from pathlib import Path
root = Path(__file__).resolve().parents[1] / 'KaoyanEnglish/Resources'
text = {'type':'string', 'minLength':1, 'pattern':r'\S'}
uid = {'type':'string','pattern':'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'}
date = {'type':'string','format':'date-time'}
def arr(items): return {'type':'array','items':items}
def opt(v): return {'anyOf':[v,{'type':'null'}]}
def obj(props, required): return {'type':'object','properties':props,'required':required}
def model(required, optional): return obj(required | {k:opt(v) for k,v in optional.items()},list(required))
strings = arr(text)
refs = arr(uid) | {'minItems':1,'uniqueItems':True}
difficulty = {'type':'integer','minimum':1,'maximum':5}
types=['reading_single_choice','cloze','seven_choose_five','ordering','heading_match','translation','practical_writing','essay_writing']
defs = {}
defs['source']=model({'id':uid,'title':text},{'url':{'type':'string','format':'uri','pattern':'^https?://'},'note':{'type':'string'}})
defs['article']=model({'id':uid,'title':text,'body':text,'kind':{'enum':['original','adapted']}},{'source_id':uid,'original_article_id':uid,'theme':text,'created_at':date})
defs['article']['allOf']=[{'if':{'properties':{'kind':{'const':'adapted'}}},'then':{'required':['original_article_id'],'properties':{'original_article_id':uid}}},{'if':{'properties':{'kind':{'const':'original'}}},'then':{'properties':{'original_article_id':{'type':'null'}}}}]
defs['vocabulary']=model({'id':uid,'expression':text,'meaning':text,'source_article_ids':refs},{'lemma':text,'part_of_speech':text,'word_family':text,'origin_id':uid,'phonetic':{'type':'string'},'english_definition':{'type':'string'},'original_sentence':{'type':'string'},'sentence_translation':{'type':'string'},'collocations':strings,'uncommon_meaning':{'type':'string'},'difficulty':difficulty,'topics':strings,'writing_value':{'type':'string'},'created_at':date,'updated_at':date})
defs['question']=model({'id':uid,'article_id':uid,'type':{'enum':types},'stem':text,'correct_answer':text,'explanation':text,'provenance':{'const':'original_simulation'}},{'options':arr(obj({'id':text,'text':text},['id','text'])),'evidence':{'type':'string'},'distractor_analysis':{'type':'object','additionalProperties':{'type':'string'}},'tested_skill':{'type':'string'},'difficulty':difficulty,'created_at':date})
defs['question']['allOf']=[{'if':{'properties':{'type':{'const':'reading_single_choice'}}},'then':{'required':['options'],'properties':{'options':arr(obj({'id':text,'text':text},['id','text']))|{'minItems':2}}}}]
defs['writing_expression']=model({'id':uid,'expression':text,'meaning':text,'source_article_ids':refs},{'topics':strings,'expression_type':{'type':'string'},'context':{'type':'string'},'original_sentence':{'type':'string'},'essay_sentence':{'type':'string'},'translation':{'type':'string'},'alternatives':strings,'usage_notes':{'type':'string'},'created_at':date})
props={'schema_version':{'const':'1.0'},'package_id':uid,'created_at':date}
for k,d in [('sources','source'),('articles','article'),('vocabulary','vocabulary'),('questions','question'),('writing_expressions','writing_expression')]: props[k]=arr({'$ref':'#/$defs/'+d})
schema={'$schema':'https://json-schema.org/draft/2020-12/schema','$id':'urn:kaoyan-english:learning-package:1.0','title':'Kaoyan English Learning Package 1.0','description':'ID 必须为小写 UUID。跨实体引用、去重与选项答案一致性由应用服务层校验。未知字段忽略，版本不匹配拒绝。',**obj(props,list(props)),'$defs':defs}
def ident(n): return f'10000000-0000-4000-8000-{n:012d}'
src,original,adapted=ident(1),ident(2),ident(3)
package={'schema_version':'1.0','package_id':ident(100),'created_at':'2026-11-10T00:00:00Z',
'sources':[{'id':src,'title':'示例学习资料：Technology and Learning','note':'离线演示用原创短文；非历年真题。'}],
'articles':[{'id':original,'title':'Technology and Learning — Original','body':'Digital tools can facilitate learning by making information more accessible. Yet access alone does not guarantee understanding. Students still need to evaluate evidence and reflect on what they read. Technology is most useful when it supports, rather than replaces, independent thought.','kind':'original','source_id':src,'theme':'科技与人工智能','created_at':'2026-11-10T00:00:00Z'},
{'id':adapted,'title':'Beyond Access: Learning in a Digital Age','body':'The rapid spread of digital tools has made information easier to obtain. Advocates argue that these tools can facilitate learning and reduce barriers to education. However, access to information should not be confused with a deeper understanding of it.\n\nA student may collect hundreds of articles without carefully considering a single argument. Effective learning therefore calls for more than efficient searching. It requires learners to assess evidence, compare perspectives and question their own assumptions.\n\nDigital technology can play a vital role in this process when it encourages reflection. Its educational value depends less on the volume of material it delivers than on the quality of thought it helps to develop. Learning outcomes reflect the quality of thought.','kind':'adapted','source_id':src,'original_article_id':original,'theme':'教育与人才培养','created_at':'2026-11-10T00:00:00Z'}],
'vocabulary':[{'id':ident(4),'expression':'facilitate','phonetic':'/fəˈsɪlɪteɪt/','meaning':'促进；使便利','original_sentence':'These tools can facilitate learning and reduce barriers to education.','sentence_translation':'这些工具能够促进学习并降低教育门槛。','collocations':['facilitate learning','facilitate communication'],'uncommon_meaning':'指使某个过程更容易进行，而非直接完成该过程。','difficulty':3,'topics':['科技与人工智能','教育与人才培养'],'writing_value':'可用于论述技术、政策或合作的积极作用。','source_article_ids':[original,adapted],'created_at':'2026-11-10T00:00:00Z','updated_at':'2026-11-10T00:00:00Z'},
{'id':ident(5),'expression':'reflect','meaning':'认真思考；反思','source_article_ids':[original],'original_sentence':'Students still need to evaluate evidence and reflect on what they read.','sentence_translation':'学生仍需评估证据并反思阅读内容。','difficulty':3,'topics':['教育与人才培养']},
{'id':ident(6),'expression':'reflect','meaning':'反映；显示','source_article_ids':[adapted],'original_sentence':'Learning outcomes reflect the quality of thought.','sentence_translation':'学习成果反映思维的质量。','difficulty':2,'topics':['教育与人才培养'],'writing_value':'可用于说明结果反映某种内在质量。'}],
'questions':[{'id':ident(7),'article_id':adapted,'type':'reading_single_choice','provenance':'original_simulation','stem':'According to the passage, the educational value of digital technology mainly depends on its ability to _____.','options':[{'id':'A','text':'deliver the largest possible amount of information'},{'id':'B','text':'replace learners’ independent judgment'},{'id':'C','text':'promote thoughtful engagement with information'},{'id':'D','text':'remove the need to compare different perspectives'}],'correct_answer':'C','explanation':'文章末段强调技术的教育价值取决于它能培养的思考质量，因此 C 正确。','evidence':'Its educational value depends less on the volume of material it delivers than on the quality of thought it helps to develop.','distractor_analysis':{'A':'与末段对信息量和思考质量的比较相反。','B':'原文强调独立思考，并非取代判断。','D':'第二段明确提出需要比较不同观点。'},'tested_skill':'主旨理解与同义替换','difficulty':3,'created_at':'2026-11-10T00:00:00Z'},
{'id':ident(8),'article_id':adapted,'type':'translation','provenance':'original_simulation','stem':'Translate: Access to information should not be confused with a deeper understanding of it.','correct_answer':'获取信息不应与深入理解信息混为一谈。','explanation':'access to 表示获取；be confused with 表示与……混淆。','evidence':'However, access to information should not be confused with a deeper understanding of it.','difficulty':3}],
'writing_expressions':[{'id':ident(9),'expression':'play a vital role in','meaning':'在……中发挥重要作用','topics':['科技与人工智能','教育与人才培养'],'expression_type':'论述作用','context':'论述某种因素对社会、教育或个人发展的贡献。','original_sentence':'Digital technology can play a vital role in this process when it encourages reflection.','essay_sentence':'Critical thinking plays a vital role in preparing students for an increasingly complex world.','translation':'批判性思维在帮助学生应对日益复杂的世界方面发挥着重要作用。','alternatives':['make a significant contribution to','be essential to'],'usage_notes':'in 后接名词或动名词；避免只写空泛的作用，宜补充具体机制。','source_article_ids':[adapted],'created_at':'2026-11-10T00:00:00Z'}]}
for name,data in [('learning-package.schema.json',schema),('sample-package.json',package)]:
    (root/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
